<?php $__env->startSection('content'); ?><div class="panel p-4"><form class="row g-2 mb-4"><div class="col-md-3"><select class="form-select" name="type"><option value="">Semua jenis</option><option value="in" <?php if(request('type')==='in'): echo 'selected'; endif; ?>>Stok Masuk</option><option value="out" <?php if(request('type')==='out'): echo 'selected'; endif; ?>>Stok Keluar</option></select></div><div class="col-md-3"><input type="date" class="form-control" name="from" value="<?php echo e(request('from')); ?>"></div><div class="col-md-3"><input type="date" class="form-control" name="to" value="<?php echo e(request('to')); ?>"></div><div class="col-md-3 d-flex gap-2"><button class="btn btn-outline-secondary">Filter</button><a href="<?php echo e(route('stock.history')); ?>" class="btn btn-light">Reset</a></div></form><div class="table-responsive"><table class="table"><thead><tr><th>Kode</th><th>Tanggal</th><th>Produk</th><th>Jenis</th><th>Jumlah</th><th>Petugas</th><th>Catatan</th></tr></thead><tbody><?php $__empty_1 = true; $__currentLoopData = $transactions; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $t): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); $__empty_1 = false; ?><tr><td><code><?php echo e($t->code); ?></code></td><td><?php echo e($t->created_at->format('d/m/Y H:i')); ?></td><td class="fw-semibold"><?php echo e($t->product->name); ?></td><td><span class="badge <?php echo e($t->type==='in'?'badge-soft':'text-bg-light'); ?>"><?php echo e($t->type==='in'?'Masuk':'Keluar'); ?></span></td><td><?php echo e($t->quantity); ?></td><td><?php echo e($t->user->name); ?></td><td><?php echo e($t->note ?: '-'); ?></td></tr><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); if ($__empty_1): ?><tr><td colspan="7" class="text-center py-5 muted">Belum ada transaksi.</td></tr><?php endif; ?></tbody></table></div><?php echo e($transactions->links()); ?></div><?php $__env->stopSection(); ?>

